import { HttpClient, HttpErrorResponse, HttpParams } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';

interface SourceItem { id: number; name: string; shortDescription?: string; description?: string; }
interface Translation {
  contentType: string; contentId: number; language: string;
  name: string; shortDescription?: string; description?: string;
  isPublished: boolean; isReviewed: boolean;
}
interface Row { id: number; name: string; translatedName?: string; isPublished: boolean; isReviewed: boolean; }
interface Response<T> { status: string; data: T; }

@Component({
  selector: 'app-catalog-translations',
  templateUrl: './catalog-translations.component.html',
  styleUrls: ['./catalog-translations.component.scss']
})
export class CatalogTranslationsComponent implements OnInit {
  types = [
    { value: 'course', label: 'دوره‌ها' },
    { value: 'product', label: 'محصولات' },
    { value: 'article', label: 'مقاله‌های آموزشی' },
    { value: 'product-article', label: 'مقاله‌های محصول' },
    { value: 'course-category', label: 'دسته‌های آموزشگاه' },
    { value: 'product-category', label: 'دسته‌های فروشگاه' },
    { value: 'course-tag', label: 'برچسب‌های دوره' },
    { value: 'product-tag', label: 'برچسب‌های محصول' },
    { value: 'article-tag', label: 'برچسب‌های مقاله' },
    { value: 'product-article-tag', label: 'برچسب‌های مقالهٔ محصول' },
    { value: 'product-further-detail', label: 'ویژگی‌های محصول' },
    { value: 'product-design', label: 'طرح‌های محصول' },
    { value: 'product-guarantee', label: 'متن ضمانت محصول' },
    { value: 'product-return', label: 'متن مرجوعی محصول' },
    { value: 'course-level', label: 'سطح دوره' }
  ];
  type = 'course';
  language = 'en';
  page = 1;
  rows: Row[] = [];
  source?: SourceItem;
  translation?: Translation;
  busy = false;
  error = '';
  message = '';

  constructor(private http: HttpClient) { }

  ngOnInit(): void { this.load(); }

  load(reset = false): void {
    if (reset) { this.page = 1; this.source = undefined; this.translation = undefined; }
    this.error = '';
    const params = new HttpParams().set('type', this.type).set('language', this.language).set('page', String(this.page));
    this.http.get<Response<{ items: Row[] }>>('/api/CatalogTranslation/Items', { params }).subscribe(
      response => this.rows = response.data.items,
      error => this.fail(error)
    );
  }

  open(row: Row): void {
    this.error = '';
    this.message = '';
    const params = new HttpParams().set('type', this.type).set('id', String(row.id)).set('language', this.language);
    this.http.get<Response<{ source: SourceItem; translation?: Translation }>>('/api/CatalogTranslation/Item', { params }).subscribe(
      response => {
        this.source = response.data.source;
        this.translation = response.data.translation || {
          contentType: this.type, contentId: row.id, language: this.language,
          name: '', shortDescription: '', description: '', isPublished: false, isReviewed: false
        };
      },
      error => this.fail(error)
    );
  }

  save(approve: boolean): void {
    if (!this.translation || this.busy || !this.translation.name.trim()) { return; }
    this.busy = true;
    this.error = '';
    this.message = '';
    const draft = { ...this.translation, isPublished: approve };
    this.http.post<Response<Translation>>('/api/CatalogTranslation/Save', draft).subscribe(
      response => {
        this.translation = response.data;
        this.busy = false;
        this.message = approve ? 'ترجمه در دیتابیس ذخیره و منتشر شد.' : 'پیش‌نویس در دیتابیس ذخیره شد و منتشر نیست.';
        this.load();
      },
      error => { this.busy = false; this.fail(error); }
    );
  }

  changePage(delta: number): void {
    if (this.page + delta < 1 || (delta > 0 && this.rows.length < 20)) { return; }
    this.page += delta;
    this.source = undefined;
    this.translation = undefined;
    this.load();
  }

  private fail(error: HttpErrorResponse): void {
    if (error.status === 503) {
      this.error = 'جدول ترجمه‌ها هنوز روی دیتابیس نصب نشده است. مایگریشن CatalogTranslations را اجرا کنید.';
      return;
    }
    this.error = typeof error.error === 'string' && error.error.length < 200
      ? error.error : 'دریافت یا ذخیرهٔ ترجمه انجام نشد.';
  }
}
